  await p.locator('[data-alias-input="li-1"]').fill('Alex实验组');await p.locator('[data-save-alias="li-1"]').click();assert.equal((await state(p)).directory.find(u=>u.id==='li-1').remark,'Alex实验组');
  await p.locator('[data-edit-member-alias="li-1"]').click();await p.locator('[data-alias-input="li-1"]').fill('');await p.locator('[data-cancel-alias]').click();assert.equal((await state(p)).directory.find(u=>u.id==='li-1').remark,'Alex实验组');
  await p.locator('[data-add-directory]').click();const contact=(await state(p)).platformAccounts.find(u=>u.id==='li-1');await p.locator('#memberAccount').fill(contact.account);assert.match(await p.locator('#matchedMemberDetails').innerText(),new RegExp(contact.phone));
