  assert.equal(saved.projects.find(p=>p.id==='pending-collab-01').members.some(m=>m.id==='chen-1'),true);
  await p.reload();assert.equal(await p.locator('[data-project-row="pending-collab-01"]').count(),0);assert.equal(await p.locator('[data-project-row="pending-collab-02"]').count(),1);
