  await p.locator('.sidebar [data-nav=spaces]').click();assert.ok(await p.locator('[data-add-projects-to-invited]').count());await p.locator('[data-add-group-projects="manager-joined-01"]').click();assert.equal(await p.locator('[data-collab-source=managed]').getAttribute('class'),'active');assert.ok(await p.locator('[data-collab-project]').count());await p.keyboard.press('Escape');
  checks.push('管理者受邀项目显示管理员；受邀课题组可添加有管理权限的项目');
